&= 3 \int_{1/3}^{1/2} \dfrac{1}{u\sqrt{1 - u^2}}\, \cdot \dfrac{1}{3}\,\textrm{d}u \[5pt]

&= \int_{1/3}^{1/2} \dfrac{\textrm{d}u}{u \sqrt{1-u^2}} \[5pt]

& = - \arsech{u}\Big|_{1/3}^{1/2}\[5pt]

&= -\left(\arsech\left(\dfrac{1}{2}\right) - \arsech\left(\dfrac{1}{3}\right) \right)\[5pt]

&= \arsech\left(\dfrac{1}{3}\right) - \arsech\left(\dfrac{1}{2}\right)

}]

